import React, { useState } from 'react';

export default function Login({ setShowLoginModal, handleLoginSubmit }) {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');

    const onSubmit = (e) => {
        e.preventDefault();
        handleLoginSubmit(username, password);
    };

    return (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.6)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000 }}>
            
            <div style={{ display: 'flex', width: '850px', height: '480px', background: 'white', borderRadius: '20px', overflow: 'hidden', boxShadow: '0 10px 30px rgba(0,0,0,0.3)' }}>
                
                {/* වම් පැත්ත: login.png රූපය */}
                <div style={{ width: '50%', position: 'relative', backgroundColor: '#145c2e' }}>
                    <img 
                        src="/login.png" 
                        alt="Login Background" 
                        style={{ width: '100%', height: '100%', objectFit: 'cover' }} 
                    />
                    
                    {/* පින්තූරේ ඇතුළෙම අකුරු නැත්නම්, මේකෙන් අකුරු පෙන්වයි. ඔයාගේ login.png එකේම අකුරු තියෙනවා නම් මේ <div> එක මකලා දාන්න. */}
                    <div style={{ position: 'absolute', top: '50%', left: '10%', transform: 'translateY(-50%)', color: 'white', zIndex: 1 }}>
                        <h2 style={{ lineHeight: '1.4', fontSize: '32px', margin: 0, fontWeight: '700' }}>
                            Aura Pan Saku<br/>Educational<br/>Institute
                        </h2>
                    </div>
                </div>
                
                {/* දකුණු පැත්ත: Form එක */}
                <div style={{ width: '50%', padding: '50px 40px', display: 'flex', flexDirection: 'column', justifyContent: 'center', position: 'relative' }}>
                    <button onClick={() => setShowLoginModal(false)} style={{ position: 'absolute', top: '20px', right: '20px', background: 'none', border: 'none', fontSize: '24px', cursor: 'pointer', color: '#999' }}>✖</button>

                    <h2 style={{ marginBottom: '30px', color: '#15803d', fontSize: '30px', fontWeight: 'bold' }}>Welcome Back!</h2>
                    
                    <form onSubmit={onSubmit} style={{ display: 'flex', flexDirection: 'column' }}>
                        
                        <label style={{ marginBottom: '8px', color: '#333', fontSize: '14px', fontWeight: 'bold' }}>User Name</label>
                        <input type="text" placeholder="Enter your user name" onChange={(e) => setUsername(e.target.value)} required style={{ padding: '14px 15px', marginBottom: '20px', border: '1px solid #e2e8f0', borderRadius: '8px', background: '#f8fafc', outline: 'none', fontSize: '14px' }} />
                        
                        <label style={{ marginBottom: '8px', color: '#333', fontSize: '14px', fontWeight: 'bold' }}>Password</label>
                        <input type="password" placeholder="Enter your password" onChange={(e) => setPassword(e.target.value)} required style={{ padding: '14px 15px', marginBottom: '20px', border: '1px solid #e2e8f0', borderRadius: '8px', background: '#f8fafc', outline: 'none', fontSize: '14px' }} />
                        
                        <p style={{ fontSize: '12px', color: '#64748b', textAlign: 'center', marginBottom: '25px', lineHeight: '1.5' }}>
                            If you have forgotten your username or password,<br/>please contact the class to retrieve it.
                        </p>
                        
                        <button type="submit" style={{ padding: '14px', background: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '16px' }}>
                            Login
                        </button>
                    </form>
                </div>

            </div>
        </div>
    );
}
